233	        if ("Sydney".equals(this.city)) {
234	            return "NSW";
235	        }
236	        if ("Melbourne".equals(this.city)) {
237	            return "VIC";
238	        }
239	        if ("Brisbane".equals(this.city)) {
240	            return "QLD";
241	        }
242	        return "UNKNOWN";
