178	    /**
179	     * The owner's numeric membership level, derived on creation: it starts at 1, gains 1 when an
180	     * email is present, gains 1 when {@link #namesakeCount} is 0, and is capped at 3 (level 4 is
181	     * reserved for tenure).
182	     */
183	    @Transient
