185	        int level = 1;
186	        if (this.email != null && !this.email.isBlank()) {
187	            level++;
188	        }
189	        if (this.namesakeCount != null && this.namesakeCount == 0) {
190	            level++;
191	        }
192	        return Math.min(level, 3);
