213	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
214	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
215	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
216	        "NSW", new int[] {2000, 2099},
217	        "VIC", new int[] {3000, 3099},
218	        "QLD", new int[] {4000, 4099});
219	
220	    /**
221	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
222	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
223	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
224	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
225	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
226	     */
227	    @Transient
228	    public String getRegion() {
229	        String byPostcode = regionForPostcode(this.postcode);
230	        if (byPostcode != null) {
231	            return byPostcode;
232	        }
233	        if ("Sydney".equals(this.city)) {
234	            return "NSW";
235	        }
236	        if ("Melbourne".equals(this.city)) {
237	            return "VIC";
238	        }
239	        if ("Brisbane".equals(this.city)) {
240	            return "QLD";
241	        }
242	        return "UNKNOWN";
243	    }
