249	    public String getLocality() {
250	        return getRegion();
251	    }
252	
253	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
254	     *  absent, not a 4-digit value, or in no known range. */
255	    private static String regionForPostcode(String postcode) {
256	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
257	            return null;
258	        }
259	        int value = Integer.parseInt(postcode);
260	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
261	            int[] range = entry.getValue();
262	            if (value >= range[0] && value <= range[1]) {
263	                return entry.getKey();
264	            }
265	        }
266	        return null;
267	    }
268	
269	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
270	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
271	     *  digit-free value yields {@code 0}. */
272	    private static int luhnCheckDigit(String value) {
273	        int sum = 0;
274	        boolean doubling = true;
275	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
276	            char c = value.charAt(i);
277	            if (c < '0' || c > '9') {
278	                continue;
279	            }
280	            int digit = c - '0';
281	            if (doubling) {
282	                digit *= 2;
283	                if (digit > 9) {
284	                    digit -= 9;
285	                }
286	            }
287	            sum += digit;
288	            doubling = !doubling;
289	        }
290	        return (10 - (sum % 10)) % 10;
291	    }
