119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        HttpHeaders headers = new HttpHeaders();
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        String address = normalizeAddress(owner.getAddress());
123	        if (address.isEmpty()) {
124	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
125	        }
126	        owner.setAddress(address);
127	        if (owner.getEmail() != null) {
128	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
129	            if (!EMAIL_PATTERN.matcher(email).matches()) {
130	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	            }
132	            owner.setEmail(email);
133	        }
134	        if (!isPostcodeValidForCity(owner)) {
135	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
136	        }
137	        String telephone = normalizeTelephone(owner.getTelephone());
138	        if (telephone == null) {
139	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
140	        }
141	        owner.setTelephone(telephone);
142	        LocalDate registrationDate = resolveRegistrationDate(owner.getRegistrationDate());
143	        owner.setRegistrationDate(registrationDate);
144	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
145	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
146	        }
147	        owner.setIdentityKey(identityKey(owner));
148	        if (isDuplicate(owner)) {
149	            return new ResponseEntity<>(HttpStatus.CONFLICT);
150	        }
151	        if (countOwnersInCity(owner.getCity()) >= 50) {
152	            return new ResponseEntity<>(HttpStatus.CONFLICT);
153	        }
154	        assignRegistrationAttributes(owner);
155	        this.clinicService.saveOwner(owner);
156	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
157	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
158	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
159	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
160	        headers.setLocation(UriComponentsBuilder.newInstance()
161	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
162	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
