172	        currentOwner.setAddress(ownerFieldsDto.getAddress());
173	        currentOwner.setCity(ownerFieldsDto.getCity());
174	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
175	        currentOwner.setLastName(ownerFieldsDto.getLastName());
176	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
177	        String email = ownerFieldsDto.getEmail();
178	        if (email != null) {
179	            email = email.trim().toLowerCase(Locale.ROOT);
180	            if (!EMAIL_PATTERN.matcher(email).matches()) {
181	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
182	            }
183	        }
184	        currentOwner.setEmail(email);
185	        this.clinicService.saveOwner(currentOwner);
186	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
187	    }
